document.getElementById('stagePrev').onclick = function () { if (list.length) { curIdx = (curIdx - 1 + list.length) % list.length; renderStage(); } };
document.getElementById('stageNext').onclick = function () { if (list.length) { curIdx = (curIdx + 1) % list.length; renderStage(); } };

/* ---------- 进入/返回（转场特效） ---------- */
var curtain = document.getElementById('curtain');
var home = document.getElementById('home');
var album = document.getElementById('album');
function enter() {
    curtain.classList.remove('play');
    void curtain.offsetWidth;
    curtain.classList.add('play');
    home.classList.add('leave');
    setTimeout(function () {
        home.classList.add('hidden');
        album.classList.remove('hidden');
        album.classList.add('enter');
        renderCats(); renderStage(); renderFilm();
        setTimeout(function () { album.classList.remove('enter'); }, 600);
    }, 430);
}
function goBack() {
    curtain.classList.remove('play');
    void curtain.offsetWidth;
    curtain.classList.add('play');
    album.classList.add('hidden');
    home.classList.remove('hidden');
    home.classList.remove('leave');
}
document.getElementById('btnEnter').onclick = enter;
document.getElementById('btnBack').onclick = goBack;
document.getElementById('btnEnter').addEventListener('keydown', function (e) { if (e.key === 'Enter') enter(); });

/* ---------- 灯箱 ---------- */
