/* 长条播放器：点击进度条跳转 */
document.getElementById('hbBar').onclick = function (e) {
    if (!audio || !audio.duration) return;
    var r = this.getBoundingClientRect();
    var p = (e.clientX - r.left) / r.width;
    if (p < 0) p = 0; if (p > 1) p = 1;
    audio.currentTime = p * audio.duration;
};


